import base64,json,os,sys,urllib.request,urllib.error,uuid
from pathlib import Path
mode=sys.argv[1]; root=Path.cwd(); work=(root/'media-work').resolve(); prompt=sys.argv[-1]
if not prompt.strip() or len(prompt)>2000: sys.exit('prompt must be 1..2000 characters')
def mime(data):
    if data.startswith(b'\x89PNG\r\n\x1a\n'): return 'image/png'
    if data.startswith(b'\xff\xd8\xff'): return 'image/jpeg'
    if data.startswith(b'RIFF') and data[8:12]==b'WEBP': return 'image/webp'
    sys.exit('only PNG, JPEG and WebP images are supported')
payload={{'model':'meta/muse-image','prompt':prompt}}; original=None
if mode=='edit':
    original=Path(sys.argv[2]).resolve(strict=True)
    if not original.is_relative_to(work) or not original.is_file(): sys.exit('image must be inside media-work')
    data=original.read_bytes()
    if not 0<len(data)<=8*1024*1024: sys.exit('image must be between 1 byte and 8 MiB')
    payload['input_references']=[{{'type':'image_url','image_url':{{'url':'data:'+mime(data)+';base64,'+base64.b64encode(data).decode()}}}}]
key=os.environ.get('OPENROUTER_API_KEY') or os.environ.get('OPENAI_API_KEY')
if not key: sys.exit('set OPENROUTER_API_KEY in the MCP server environment')
req=urllib.request.Request('https://openrouter.ai/api/v1/images',json.dumps(payload).encode(),{{'Authorization':'Bearer '+key,'Content-Type':'application/json'}},method='POST')
try:
    with urllib.request.urlopen(req,timeout=180) as response: body=response.read(16*1024*1024+1)
except urllib.error.HTTPError as error: sys.exit('OpenRouter images returned HTTP '+str(error.code))
if len(body)>16*1024*1024: sys.exit('OpenRouter response exceeds 16 MiB')
encoded=json.loads(body)['data'][0]['b64_json']
if len(encoded)>8*1024*1024*4//3+8: sys.exit('generated image exceeds 8 MiB')
image=base64.b64decode(encoded,validate=True)
suffix={{'image/png':'.png','image/jpeg':'.jpg','image/webp':'.webp'}}[mime(image)]
dest=work/'edits'; dest.mkdir(parents=True,exist_ok=True)
target=dest/(uuid.uuid4().hex+suffix); target.write_bytes(image)
print(json.dumps({{'original':str(original) if original else None,'edited':str(target),'model':'meta/muse-image'}}))

