import base64,json,os,sys,urllib.request,urllib.error
from pathlib import Path
work=(Path.cwd()/'media-work').resolve(); prompt=sys.argv[3]
if not prompt.strip() or len(prompt)>2000: sys.exit('prompt must be 1..2000 characters')
def image(path):
    path=Path(path).resolve(strict=True)
    if not path.is_relative_to(work) or not path.is_file(): sys.exit('image must be inside media-work')
    data=path.read_bytes()
    if not 0<len(data)<=8*1024*1024: sys.exit('image must be between 1 byte and 8 MiB')
    if data.startswith(b'\x89PNG\r\n\x1a\n'): mime='image/png'
    elif data.startswith(b'\xff\xd8\xff'): mime='image/jpeg'
    elif data.startswith(b'RIFF') and data[8:12]==b'WEBP': mime='image/webp'
    else: sys.exit('only PNG, JPEG and WebP images are supported')
    return {{'type':'image_url','image_url':{{'url':'data:'+mime+';base64,'+base64.b64encode(data).decode()}}}}
content=[{{'type':'text','text':prompt}},image(sys.argv[1]),image(sys.argv[2])]
key=os.environ.get('OPENROUTER_API_KEY') or os.environ.get('OPENAI_API_KEY')
if not key: sys.exit('set OPENROUTER_API_KEY in the MCP server environment')
payload={{'model':'deepseek/deepseek-v4.1-flash','messages':[{{'role':'user','content':content}}]}}
req=urllib.request.Request('https://openrouter.ai/api/v1/chat/completions',json.dumps(payload).encode(),{{'Authorization':'Bearer '+key,'Content-Type':'application/json'}},method='POST')
try:
    with urllib.request.urlopen(req,timeout=180) as response: body=response.read(16*1024*1024+1)
except urllib.error.HTTPError as error: sys.exit('OpenRouter comparison returned HTTP '+str(error.code))
if len(body)>16*1024*1024: sys.exit('OpenRouter response exceeds 16 MiB')
answer=json.loads(body)['choices'][0]['message']['content']
if not isinstance(answer,str) or not answer.strip(): sys.exit('comparison model returned no text')
print(json.dumps({{'model':'deepseek/deepseek-v4.1-flash','description':answer}},ensure_ascii=False))
